import React, { FC } from "react";
import { graphql, HeadFC, PageProps } from "gatsby";
import IndexContents from "../components/index/contents";
import SEO from '../components/SEO'
import { buildWebSite } from "../utils/jsonLd";
import { Recommend } from "../types/recommend";
import { HomeArticle, SiteStats } from "../components/index/sections/HomeSection";
import { isReleased, useNow } from "../utils/songArticles/schedule";
import { DEFAULT_LANG, isSiteLang } from "../i18n/site/langs";

type siteMetadata = {
  title: string;
  description: string;
  siteUrl: string;
};

export const query = graphql`
  query IndexPage {
    site {
      siteMetadata {
        title
        description
        siteUrl
      }
    }
    recommend {
      recommend {
        no
        id
      }
    }
    siteStats {
      siteStats {
        songCount
        liveItemCount
        performanceCount
        nextLive {
          title
          itemName
          date
          place
        }
      }
    }
  }
`;

const IndexPage: FC<PageProps<any, { lang?: string; homeArticles?: HomeArticle[]; builtAt?: number }>> = ({ data, pageContext }) => {
  const recommend: Recommend[] = data.recommend.recommend;
  const siteStats: SiteStats = data.siteStats.siteStats;
  // 読みもの(楽曲記事)は日本語だけなので、日本語の HOME にだけ出す
  // 予約公開(plan/43)の記事は、公開日時を過ぎるまで出さない
  const now = useNow(pageContext?.builtAt);
  const homeArticles = pageContext?.lang ? [] : (pageContext?.homeArticles ?? []).filter((a) => isReleased(a.publishedAt, now));

  return (
    <>
      <main className="relative bg-transparent mx-auto inset-auto w-screen">
        <IndexContents
          recommend={recommend}
          siteStats={siteStats}
          homeArticles={homeArticles}
        />
      </main>
      {/* フッター(公式リンク・運営情報)は Body 共通の OfficialFooter に統合 */}
    </>
  );
};

export default IndexPage;

export const Head: HeadFC<any, { lang?: string }> = ({ data, pageContext }) => {
  const siteMetadata: siteMetadata = data.site.siteMetadata;
  const lang = isSiteLang(pageContext?.lang) ? pageContext.lang : DEFAULT_LANG;
  // ?section=place などのクエリがあればセクション別タイトル/OGに反映
  // Gatsby v5 の Head の location は pathname しか持たないため、ブラウザ側で
  // 取得できる場合のみ参照する
  const search =
    typeof window !== "undefined" && typeof window.location?.search === "string"
      ? window.location.search
      : "";
  const section = (() => {
    const m = search.match(/[?&]section=([^&]+)/);
    return m ? decodeURIComponent(m[1]) : undefined;
  })();
  return (
    <SEO
      // 日本語以外は SEO 側の言語別の既定 description を使う(siteMetadata は日本語)
      description={lang === DEFAULT_LANG ? siteMetadata.description : undefined}
      path="/"
      section={lang === DEFAULT_LANG ? section : undefined}
      jsonLd={buildWebSite()}
      lang={lang}
    />
  );
};
